import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        S = next(iterator)
        n = len(S)

        seen = set()

        for i in range(n):
            current_ones = 0
            prefix_ones = 0

            for j in range(i, n):
                if S[j] == '1':
                    current_ones += 1

                total_ones = current_ones
                first_char = S[i]
                last_char = S[j]

                key = (total_ones, first_char, last_char)
                seen.add(key)

        results.append(str(len(seen)))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
